    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find monochrome horizontal runs of length at least two.
    runs = []
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            color, start = row[c], c
            while c < w and row[c] == color:
                c += 1
            if c - start >= 2:
                runs.append((r, start, c, color))

    if not runs:
        return [row[:] for row in grid]

    bar_color = Counter(run[3] for run in runs).most_common(1)[0][0]
    bars = [run for run in runs if run[3] == bar_color]
    marker_cells = [
        (r, c) for r in range(h) for c in range(w)
        if grid[r][c] != bg and grid[r][c] != bar_color
    ]
    fill = grid[marker_cells[0][0]][marker_cells[0][1]] if marker_cells else bar_color
    out = [row[:] for row in grid]

    # Project vertical rays from bars on the top and bottom edges;
    # a marker terminates a ray and is highlighted.
    for r, start, end, _ in bars:
        direction = 1 if r == 0 else (-1 if r == h - 1 else 0)
        if not direction:
            continue
        for c in range(start, end):
            rr = r + direction
            while 0 <= rr < h:
                if grid[rr][c] != bg and grid[rr][c] != bar_color:
                    out[rr][c] = 4
                    break
                out[rr][c] = fill
                rr += direction

    for r, c in marker_cells:
        out[r][c] = 4

    return out
